#include <iostream>
#include <string>
#include <unordered_map>
#include <list>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long cap, q;
    if (!(std::cin >> cap >> q)) return 0;

    /* Most recently used at the front. The map holds an iterator into the
       list, so touching a key is a splice rather than a search. */
    std::list<long long> order;
    std::unordered_map<long long, std::pair<long long, std::list<long long>::iterator>> table;

    for (long long i = 0; i < q; ++i) {
        std::string op;
        if (!(std::cin >> op)) break;

        if (op == "PUT") {
            long long k, v;
            std::cin >> k >> v;
            auto it = table.find(k);
            if (it != table.end()) {
                it->second.first = v;
                order.erase(it->second.second);
                order.push_front(k);
                it->second.second = order.begin();
            } else {
                if ((long long)table.size() == cap) {
                    long long victim = order.back();
                    order.pop_back();
                    table.erase(victim);
                }
                order.push_front(k);
                table[k] = {v, order.begin()};
            }
        } else {
            long long k;
            std::cin >> k;
            auto it = table.find(k);
            if (it == table.end()) {
                std::cout << "-1\n";
            } else {
                order.erase(it->second.second);
                order.push_front(k);
                it->second.second = order.begin();
                std::cout << it->second.first << "\n";
            }
        }
    }
    return 0;
}

