import sys
from collections import OrderedDict

data = sys.stdin.read().split()
if not data:
    sys.exit(0)

cap = int(data[0])
q = int(data[1])
pos = 2

cache = OrderedDict()
out = []

for _ in range(q):
    op = data[pos]
    pos += 1
    if op == "PUT":
        k = int(data[pos]); v = int(data[pos + 1]); pos += 2
        if k in cache:
            cache.move_to_end(k)
            cache[k] = v
        else:
            if len(cache) == cap:
                cache.popitem(last=False)
            cache[k] = v
    else:
        k = int(data[pos]); pos += 1
        if k in cache:
            cache.move_to_end(k)
            out.append(str(cache[k]))
        else:
            out.append("-1")

for line in out:
    print(line)

