const data = readStdin().split(/\s+/).filter(s => s.length > 0);
if (data.length === 0) { /* nothing to do */ } else {
  const cap = Number(data[0]);
  const q = Number(data[1]);
  let pos = 2;

  /* A JS Map preserves insertion order, so delete-then-set is move-to-end. */
  const cache = new Map();

  for (let i = 0; i < q; i += 1) {
    const op = data[pos]; pos += 1;
    if (op === 'PUT') {
      const k = Number(data[pos]); const v = Number(data[pos + 1]); pos += 2;
      if (cache.has(k)) cache.delete(k);
      else if (cache.size === cap) cache.delete(cache.keys().next().value);
      cache.set(k, v);
    } else {
      const k = Number(data[pos]); pos += 1;
      if (!cache.has(k)) {
        print('-1');
      } else {
        const v = cache.get(k);
        cache.delete(k);
        cache.set(k, v);
        print(String(v));
      }
    }
  }
}
